// Package worker holds the River jobs of the identity module. Job args carry only the user ID:
// tokens are generated by the worker at send time so they are never stored in the job queue.
package worker

import (
	"context"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/riverqueue/river"

	"github.com/lhbotero1985/booking-platform-backend/internal/platform/jobs"
)

// coalescedEmailOpts: requests for the same user within one minute are merged into one job,
// which also throttles "resend" style endpoints.
func coalescedEmailOpts() river.InsertOpts {
	return river.InsertOpts{
		Queue:       jobs.QueueNotifications,
		MaxAttempts: 8,
		UniqueOpts:  river.UniqueOpts{ByArgs: true, ByPeriod: time.Minute},
	}
}

// SendVerificationEmailArgs schedules a verification email.
type SendVerificationEmailArgs struct {
	UserID uuid.UUID `json:"user_id"`
}

// Kind implements river.JobArgs.
func (SendVerificationEmailArgs) Kind() string { return "identity.send_verification_email" }

// InsertOpts implements river.JobArgsWithInsertOpts.
func (SendVerificationEmailArgs) InsertOpts() river.InsertOpts { return coalescedEmailOpts() }

// SendPasswordResetEmailArgs schedules a password reset email.
type SendPasswordResetEmailArgs struct {
	UserID uuid.UUID `json:"user_id"`
}

// Kind implements river.JobArgs.
func (SendPasswordResetEmailArgs) Kind() string { return "identity.send_password_reset_email" }

// InsertOpts implements river.JobArgsWithInsertOpts.
func (SendPasswordResetEmailArgs) InsertOpts() river.InsertOpts { return coalescedEmailOpts() }

// SendPasswordChangedEmailArgs schedules the "password changed" notice. Not coalesced: every
// change must be reported.
type SendPasswordChangedEmailArgs struct {
	UserID uuid.UUID `json:"user_id"`
}

// Kind implements river.JobArgs.
func (SendPasswordChangedEmailArgs) Kind() string { return "identity.send_password_changed_email" }

// InsertOpts implements river.JobArgsWithInsertOpts.
func (SendPasswordChangedEmailArgs) InsertOpts() river.InsertOpts {
	return river.InsertOpts{Queue: jobs.QueueNotifications, MaxAttempts: 8}
}

// Sender is the set of use cases the workers invoke.
type Sender interface {
	SendVerificationEmail(ctx context.Context, userID uuid.UUID) error
	SendPasswordResetEmail(ctx context.Context, userID uuid.UUID) error
	SendPasswordChangedEmail(ctx context.Context, userID uuid.UUID) error
}

const emailTimeout = 30 * time.Second

// SendVerificationEmailWorker runs SendVerificationEmailArgs jobs.
type SendVerificationEmailWorker struct {
	river.WorkerDefaults[SendVerificationEmailArgs]
	sender Sender
}

// Work implements river.Worker.
func (w *SendVerificationEmailWorker) Work(ctx context.Context, job *river.Job[SendVerificationEmailArgs]) error {
	return w.sender.SendVerificationEmail(ctx, job.Args.UserID)
}

// Timeout bounds one delivery attempt (SMTP included).
func (w *SendVerificationEmailWorker) Timeout(*river.Job[SendVerificationEmailArgs]) time.Duration {
	return emailTimeout
}

// SendPasswordResetEmailWorker runs SendPasswordResetEmailArgs jobs.
type SendPasswordResetEmailWorker struct {
	river.WorkerDefaults[SendPasswordResetEmailArgs]
	sender Sender
}

// Work implements river.Worker.
func (w *SendPasswordResetEmailWorker) Work(ctx context.Context, job *river.Job[SendPasswordResetEmailArgs]) error {
	return w.sender.SendPasswordResetEmail(ctx, job.Args.UserID)
}

// Timeout bounds one delivery attempt.
func (w *SendPasswordResetEmailWorker) Timeout(*river.Job[SendPasswordResetEmailArgs]) time.Duration {
	return emailTimeout
}

// SendPasswordChangedEmailWorker runs SendPasswordChangedEmailArgs jobs.
type SendPasswordChangedEmailWorker struct {
	river.WorkerDefaults[SendPasswordChangedEmailArgs]
	sender Sender
}

// Work implements river.Worker.
func (w *SendPasswordChangedEmailWorker) Work(ctx context.Context, job *river.Job[SendPasswordChangedEmailArgs]) error {
	return w.sender.SendPasswordChangedEmail(ctx, job.Args.UserID)
}

// Timeout bounds one delivery attempt.
func (w *SendPasswordChangedEmailWorker) Timeout(*river.Job[SendPasswordChangedEmailArgs]) time.Duration {
	return emailTimeout
}

// Register adds the identity workers to workers.
func Register(workers *river.Workers, sender Sender) error {
	for _, add := range []func() error{
		func() error { return river.AddWorkerSafely(workers, &SendVerificationEmailWorker{sender: sender}) },
		func() error { return river.AddWorkerSafely(workers, &SendPasswordResetEmailWorker{sender: sender}) },
		func() error { return river.AddWorkerSafely(workers, &SendPasswordChangedEmailWorker{sender: sender}) },
	} {
		if err := add(); err != nil {
			return fmt.Errorf("identity worker: %w", err)
		}
	}
	return nil
}
